package cli

import "io"

const fishCompletions = `# Fish completions for yati
# Generated by: yati completion fish

function __yati_subcommand_is
    set -l cmd (commandline -opc)
    contains -- $argv[1] $cmd[2..]
end

function __yati_needs_subcommand
    set -l cmd (commandline -opc)
    test (count $cmd) -eq 1
end

function __yati_list_periods
    echo -e "d\tToday"
    echo -e "w\tThis work-week"
    echo -e "m\tThis month"
end

# Disable file completions by default
complete -c yati -f

# Global flags
complete -c yati -l token -d 'Toggl API token'
complete -c yati -l pass-path -d 'Path to token in pass'

# Subcommands (only when no subcommand given yet)
complete -c yati -n __yati_needs_subcommand -a start -d 'Start a new time entry'
complete -c yati -n __yati_needs_subcommand -a s -d 'Start a new time entry'
complete -c yati -n __yati_needs_subcommand -a stop -d 'Stop the current time entry'
complete -c yati -n __yati_needs_subcommand -a S -d 'Stop the current time entry'
complete -c yati -n __yati_needs_subcommand -a continue -d 'Continue the most recently stopped time entry'
complete -c yati -n __yati_needs_subcommand -a c -d 'Continue the most recently stopped time entry'
complete -c yati -n __yati_needs_subcommand -a show -d 'Show the current running time entry'
complete -c yati -n __yati_needs_subcommand -a w -d 'Show the current running time entry'
complete -c yati -n __yati_needs_subcommand -a interactive -d 'Start a task interactively'
complete -c yati -n __yati_needs_subcommand -a i -d 'Start a task interactively'
complete -c yati -n __yati_needs_subcommand -a list -d 'List tasks for a period'
complete -c yati -n __yati_needs_subcommand -a ls -d 'List tasks for a period'
complete -c yati -n __yati_needs_subcommand -a completion -d 'Output shell completion script'
complete -c yati -n __yati_needs_subcommand -a gui -d 'Open the desktop quick-entry window'

# Desktop options
complete -c yati -n '__yati_subcommand_is gui' -s d -l detach -d 'Detach from the terminal'
complete -c yati -n '__yati_subcommand_is gui' -l background -d 'Start in the tray'
complete -c yati -n '__yati_subcommand_is gui' -l toggle -d 'Toggle the quick-entry window'
complete -c yati -n '__yati_subcommand_is gui' -l quit -d 'Quit the resident desktop app'
complete -c yati -n '__yati_subcommand_is gui' -l install -d 'Install the application launcher and icon'
complete -c yati -n '__yati_subcommand_is gui' -l autostart -d 'Enable login startup'
complete -c yati -n '__yati_subcommand_is gui' -l no-tray -d 'Disable the tray icon'

# start flags
complete -c yati -n '__yati_subcommand_is start s' -s p -d 'Toggl project, or pick interactively'

# list period argument
complete -c yati -n '__yati_subcommand_is list ls' -a '(__yati_list_periods)' -d 'Period'
`

func PrintFishCompletions(w io.Writer) {
	w.Write([]byte(fishCompletions))
}
